using System.Diagnostics;
using TextAnalysis;

const string SampleText =
    "The quick brown fox jumps over the lazy dog. " +
    "A journey of a thousand miles begins with a single step. " +
    "To be or not to be that is the question. " +
    "All that glitters is not gold. " +
    "The only thing we have to fear is fear itself. " +
    "In the middle of difficulty lies opportunity. " +
    "Life is what happens when you are busy making other plans. " +
    "The greatest glory in living lies not in never falling but in rising every time we fall. " +
    "You must be the change you wish to see in the world. " +
    "It does not matter how slowly you go as long as you do not stop.";

var analyzer = new TextAnalyzer(SampleText);

// Warmup
for (int i = 0; i < 1000; i++)
{
    analyzer.AverageWordLength();
    analyzer.WordLengthHistogram();
    analyzer.UniqueWordCount();
}

const int Iterations = 500_000;
const int Runs = 5;

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations per run: {Iterations:N0}");
Console.WriteLine();

Benchmark("AverageWordLength", () => analyzer.AverageWordLength());
Benchmark("WordLengthHistogram", () => { analyzer.WordLengthHistogram(); });
Benchmark("UniqueWordCount", () => analyzer.UniqueWordCount());

void Benchmark(string name, Action action)
{
    var times = new double[Runs];
    for (int run = 0; run < Runs; run++)
    {
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();

        var sw = Stopwatch.StartNew();
        for (int i = 0; i < Iterations; i++)
            action();
        sw.Stop();
        times[run] = sw.Elapsed.TotalMilliseconds / Iterations * 1_000_000; // ns per op
    }

    Array.Sort(times);
    double median = times[Runs / 2];
    double min = times[0];
    double max = times[Runs - 1];
    Console.WriteLine($"{name,-25} median: {median,10:F1} ns/op  (min: {min:F1}, max: {max:F1})");
}

